"""V18: full manager coverage and raw evidence delivery. No AI calls in installer."""
import argparse,base64,fcntl,hashlib,io,json,os,sqlite3,subprocess,sys,tempfile,time,zipfile
from pathlib import Path
sys.dont_write_bytecode=True
BEFORE={'manager_remembered_runtime.py': 'e494acaf59d840c7c256859ee9bbe982c091afa8d59edf415e1503cc01a4160e', 'manager_memory_inputs.py': '870d8662e09282ae893327f0024958508e18488b06fe58873b6726ac48097032', 'collector.py': '4706893ab8b66c6a86d727193b5db14faf4846d04278959545aad14d5e92b566', 'manager_evidence_recovery.py': '95d54b3c210c98a6a8a1bf70d02e3ea00c3c7275e4e67723ffb0897e015a4680'}
ARCHIVE=''

MANAGER='dj-remembered-manager.service'
TIMER='dj-remembered-manager.timer'
COLLECTOR='dj-collector.service'

def sha(raw):return hashlib.sha256(raw).hexdigest()
def sources():
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(ARCHIVE))) as z:
        return {n:z.read(n) for n in z.namelist()}
def read(path):return json.loads(path.read_text(encoding='utf-8-sig'))
def atomic(target,raw):
    mode=target.stat().st_mode & 0o777 if target.exists() else 0o600
    fd,tmp=tempfile.mkstemp(dir=target.parent,prefix='.coverage-install-')
    try:
        with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
        os.chmod(tmp,mode);os.replace(tmp,target)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)

class Services:
    def active(self,name):
        return subprocess.check_output(['systemctl','show',name,'-p','ActiveState','--value'],text=True).strip()
    def stop(self,name):subprocess.run(['sudo','-n','systemctl','stop',name],check=True)
    def start(self,name):subprocess.run(['sudo','-n','systemctl','start',name],check=True)

def targets(root,code,files):
    result={}
    for name,raw in files.items():
        if name=='collector.py':result[root/name]=raw
        else:result[code/name]=raw
    result[root/'manager_evidence_storage.py']=files['manager_evidence_storage.py']
    return result

def inspect(root,files):
    state=root/'dj-manager-memory/runtime';active=read(state/'ACTIVATED.json')
    code=Path(active['code']).resolve();code.relative_to((root/'dj-manager-memory/runtime-code').resolve())
    result=targets(root,code,files)
    for path,new in result.items():
        if path.is_symlink():raise ValueError('링크 경로 차단: '+str(path))
        if path.exists():
            old=path.read_bytes()
            if old!=new and sha(old)!=BEFORE.get(path.name):
                raise ValueError('예상과 다른 운영 파일 · 변경 없음: '+path.name+' SHA256='+sha(old))
        elif path.name in BEFORE:
            raise ValueError('운영 원본 파일 없음: '+str(path))
        compile(new.decode('utf-8-sig'),str(path),'exec')
    return state,code,result

def install(root,apply=False,services=None):
    files=sources();state,code,result=inspect(root,files)
    changes={p:raw for p,raw in result.items() if not p.exists() or p.read_bytes()!=raw}
    print('운영 소스 버전·문법 확인 PASS · 설치 중 AI 요청 0회',flush=True)
    if not apply:return None
    if not changes:
        print('V18 이미 적용됨 · 추가 변경 없음',flush=True);return None
    services=services or Services()
    if services.active(MANAGER) not in ('inactive','failed'):
        raise ValueError('관리자 분석 실행 중 · 중단시키지 않고 변경 보류. 종료 후 같은 명령 실행')
    if (state/'PAUSED.json').exists():raise ValueError('기존 분석 중단 사유가 있어 자동 해제하지 않습니다')
    for path in (state/'cycles').glob('*/inputs.json'):
        if not all((path.parent/e/'completed.json').exists() for e in ('official','robot_proto','v2','v3')):
            raise ValueError('이전 분석 주기 미완료 · 기록 보존 후 적용 보류: '+path.parent.name)
    timer_active=services.active(TIMER)=='active';collector_active=services.active(COLLECTOR)=='active'
    stopped_timer=stopped_collector=False
    try:
        if timer_active:services.stop(TIMER);stopped_timer=True
        with (state/'worker.lock').open('a') as lock:
            fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
            if services.active(MANAGER) not in ('inactive','failed') or (state/'PAUSED.json').exists():
                raise ValueError('적용 직전 실행 상태 변경 · 적용 보류')
            old={p:(p.read_bytes() if p.exists() else None) for p in changes}
            backup=state/'deployments'/('coverage-v18-'+str(time.time_ns()));backup.mkdir(parents=True,mode=0o700)
            manifest=[]
            for index,(path,raw) in enumerate(old.items()):
                record=backup/f'{index:02d}-{path.name}.before'
                if raw is not None:record.write_bytes(raw)
                manifest.append({'path':str(path),'backup':record.name if raw is not None else None,'before_sha256':sha(raw) if raw is not None else None,'after_sha256':sha(changes[path])})
            (backup/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
            if collector_active:services.stop(COLLECTOR);stopped_collector=True
            _,_,verified=inspect(root,files)
            for path,raw in old.items():
                if (path.read_bytes() if path.exists() else None)!=raw:raise ValueError('검사 중 소스 변경 · 적용 중단')
            changed=[]
            try:
                for path,new in changes.items():
                    atomic(path,new);changed.append(path)
                for path,new in changes.items():
                    if path.read_bytes()!=new:raise ValueError('설치 후 해시 불일치')
                (backup/'installed.json').write_text(json.dumps({'installed_at':time.time(),'AI_requests':0,'DB_changes':0,'files':{str(p):sha(v) for p,v in changes.items()}},indent=2))
            except BaseException:
                for path in reversed(changed):
                    if old[path] is None:path.unlink()
                    else:atomic(path,old[path])
                raise
            print('FULL_COVERAGE_V18_READY · 백업: '+str(backup),flush=True)
            print('기억·완료 답안·기존 동결픽·DB 보존 · 전체 후보 비교 경로 적용',flush=True)
            return backup
    finally:
        restart_errors=[]
        for name,stopped in ((COLLECTOR,stopped_collector),(TIMER,stopped_timer)):
            if stopped:
                try:services.start(name)
                except Exception as error:restart_errors.append(name+': '+type(error).__name__)
        if restart_errors:raise RuntimeError('소스 보존 · 서비스 재시작 확인 필요: '+', '.join(restart_errors))

def diagnose(root):
    # Use the proposed read-only bridge in isolation; no collector import, AI, or DB writes.
    files=sources()
    with tempfile.TemporaryDirectory(prefix='dj-coverage-check-') as tmp:
        folder=Path(tmp)
        for name in ('manager_memory_inputs.py','manager_evidence_storage.py','manager_evidence_recovery.py'):
            (folder/name).write_bytes(files[name])
        sys.path.insert(0,str(folder))
        try:
            from manager_memory_inputs import load_pool
            data=load_pool(root)
        finally:sys.path.pop(0)
    print('\n===== V18 입력 진단 · 원본 변경 없음 =====')
    print('서버 프로토 카드:',data['source_card_count'],'/ 자료 연결 완료:',len(data['pool']))
    observations=sum(q['source'].get('evidence_storage')=='robot_pre_match_observations' for q in data['pool'])
    print('픽 없이 보존된 원자료 연결:',observations,'경기')
    for q in data['pool']:
        print('검토 대상:',q['identity']['home'],'vs',q['identity']['away'])
    for item in data['excluded']:
        if item.get('evidence_missing') or item.get('odds_missing'):
            print('수집/저장 대기:',item.get('home'), 'vs',item.get('away'),'|',item['reason'])
        elif item.get('reason')!='시작 전 시각 확인 불가 또는 이미 시작':
            print('연결 확인:',item['match_id'],'|',item['reason'])
            with sqlite3.connect((root/'ai_predictions.db').resolve().as_uri()+'?mode=ro',uri=True,timeout=5) as db:
                rows=db.execute('SELECT api_fixture_id,home_team,away_team,match_time,is_toto14,actual_result FROM predictions WHERE match_id=? ORDER BY id DESC LIMIT 2',(item['match_id'],)).fetchall()
                for row in rows:print('  DB 기록:',row)
    return data

def status(root):
    state=root/'dj-manager-memory/runtime'
    paths=sorted((state/'cycles').glob('full-coverage-v18-*/inputs.json'),key=lambda p:p.stat().st_mtime,reverse=True)
    if not paths:print('V18 전체 검토 주기 아직 시작 전');return
    cycle=paths[0].parent;data=read(paths[0]);print('전체 후보:',len(data['inputs']['pool']),'주기:',cycle.name)
    for engine in ('official','robot_proto','v2','v3'):
        path=cycle/engine/'completed.json'
        if not path.exists():print(engine,': 진행/대기 중');continue
        report=read(path);print(engine,': 검토',report.get('reviewed_count'),'/',report.get('pool_count'),'/ 답안 재사용',report.get('cached_count'),'/ 추가 선택',report.get('proposed_count'),'/ 신규 저장',len(report.get('frozen',[])))

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--apply',action='store_true');ap.add_argument('--status',action='store_true');args=ap.parse_args();root=Path('/home/ubuntu')
    if args.status:status(root);return
    try:install(root,args.apply);diagnose(root)
    except (ValueError,RuntimeError,OSError,subprocess.CalledProcessError) as error:raise SystemExit(str(error))
if __name__=='__main__':os.umask(0o077);main()
